@file:Suppress("unused")package utilsimport Dependencyimport org.gradle.kotlin.dsl.DependencyHandlerScopeimport org.gradle.api.artifacts.Dependency as GradleDependencyclass BomScope(private val scope: DependencyHandlerScope) {	fun attach(dependency: Dependency): GradleDependency? = scope.add("implementation", dependency.scheme)	fun debug(dependency: Dependency): GradleDependency? = scope.add("debugImplementation", dependency.scheme)}